import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/**
 * Strategy that orders tracks by rating descending. For equal ratings the original insertion order is preserved.
 */
public class RatingOrderStrategy implements PlaybackStrategy {
    public RatingOrderStrategy() {
        // no state needed
    }

    @Override
    public List<Track> order(Playlist playlist) {
        List<Track> result = new ArrayList<>(playlist.getTracks());
        // Collections.sort is stable; sort by rating descending
        result.sort(Comparator.comparingInt(Track::getRating).reversed());
        return result;
    }
}
