/**
 * Playback strategy that orders tracks primarily by rating in descending order.
 * For tracks with equal rating the original insertion order is preserved (stable sort).
 */
public class RatingOrderStrategy implements PlaybackStrategy {
    /** Creates a new {@code RatingOrderStrategy}. */
    public RatingOrderStrategy() {
        // no‑op
    }

    @Override
    public List<Track> order(Playlist playlist) {
        List<Track> copy = new ArrayList<>(playlist.getTracks());
        // Stable sort: Comparator is stable in List.sort (TimSort).
        copy.sort((t1, t2) -> Integer.compare(t2.getRating(), t1.getRating()));
        return copy;
    }
