public class StrategyTest {

    private Playlist createSamplePlaylist() {
        Playlist playlist = new Playlist();
        playlist.addTrack(new Track("A", "Artist1", 3, 180));
        playlist.addTrack(new Track("B", "Artist2", 5, 200));
        playlist.addTrack(new Track("C", "Artist3", 5, 210));
        return playlist;
    }

    private Object instantiateStrategy(String className) throws Exception {
        Class<?> clazz = Class.forName(className);
        Constructor<?> ctor = clazz.getConstructor();
        return ctor.newInstance();
    }

    private List<Track> invokeOrder(Object strategy, Playlist playlist) throws Exception {
        Method orderMethod = strategy.getClass().getMethod("order", Playlist.class);
        @SuppressWarnings("unchecked")
        List<Track> result = (List<Track>) orderMethod.invoke(strategy, playlist);
        return result;
    }

    // InsertionOrderStrategy – empty playlist
    @Test
    @StrictTimeout(1)
    public void testInsertionOrderEmpty() throws Exception {
        Playlist empty = new Playlist();
        Object strat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.InsertionOrderStrategy");
        List<Track> order = invokeOrder(strat, empty);
        Assertions.assertTrue(order.isEmpty(), "InsertionOrderStrategy should return empty list for empty playlist");
    }

    // InsertionOrderStrategy – non‑empty playlist
    @Test
    @StrictTimeout(1)
    public void testInsertionOrderNonEmpty() throws Exception {
        Playlist playlist = createSamplePlaylist();
        Object strat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.InsertionOrderStrategy");
        List<Track> order = invokeOrder(strat, playlist);
        Assertions.assertEquals(playlist.getTracks(), order, "InsertionOrderStrategy must preserve insertion order");
    }

    // RatingOrderStrategy – empty playlist
    @Test
    @StrictTimeout(1)
    public void testRatingOrderEmpty() throws Exception {
        Playlist empty = new Playlist();
        Object strat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.RatingOrderStrategy");
        List<Track> order = invokeOrder(strat, empty);
        Assertions.assertTrue(order.isEmpty(), "RatingOrderStrategy should return empty list for empty playlist");
    }

    // RatingOrderStrategy – distinct ratings
    @Test
    @StrictTimeout(1)
    public void testRatingOrderDistinct() throws Exception {
        Playlist playlist = new Playlist();
        playlist.addTrack(new Track("Low", "A", 1, 100));
        playlist.addTrack(new Track("Mid", "B", 3, 120));
        playlist.addTrack(new Track("High", "C", 5, 150));
        Object strat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.RatingOrderStrategy");
        List<Track> order = invokeOrder(strat, playlist);
        List<Track> expected = new ArrayList<>();
        expected.add(new Track("High", "C", 5, 150));
        expected.add(new Track("Mid", "B", 3, 120));
        expected.add(new Track("Low", "A", 1, 100));
        Assertions.assertEquals(expected, order, "RatingOrderStrategy must sort by rating descending");
    }

    // RatingOrderStrategy – tie handling (stable)
    @Test
    @StrictTimeout(1)
    public void testRatingOrderTie() throws Exception {
        Playlist playlist = createSamplePlaylist(); // A(3), B(5), C(5)
        Object strat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.RatingOrderStrategy");
        List<Track> order = invokeOrder(strat, playlist);
        List<Track> expected = new ArrayList<>();
        expected.add(new Track("B", "Artist2", 5, 200));
        expected.add(new Track("C", "Artist3", 5, 210));
        expected.add(new Track("A", "Artist1", 3, 180));
        Assertions.assertEquals(expected, order, "RatingOrderStrategy must keep insertion order for equal ratings");
    }

    // Player delegating to InsertionOrderStrategy
    @Test
    @StrictTimeout(1)
    public void testPlayerInsertion() throws Exception {
        Playlist playlist = createSamplePlaylist();
        Object insertionStrat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.InsertionOrderStrategy");
        // instantiate Player via reflection
        Class<?> playerClass = Class.forName("de.tum.cit.aet.exgenplaylistorderingstrategies.Player");
        Constructor<?> ctor = playerClass.getConstructor(PlaybackStrategy.class);
        Object player = ctor.newInstance(insertionStrat);
        Method getPlaybackOrder = playerClass.getMethod("getPlaybackOrder", Playlist.class);
        @SuppressWarnings("unchecked")
        List<Track> order = (List<Track>) getPlaybackOrder.invoke(player, playlist);
        Assertions.assertEquals(playlist.getTracks(), order, "Player should delegate to InsertionOrderStrategy");
    }

    // Player delegating to RatingOrderStrategy
    @Test
    @StrictTimeout(1)
    public void testPlayerRating() throws Exception {
        Playlist playlist = createSamplePlaylist();
        Object ratingStrat = instantiateStrategy("de.tum.cit.aet.exgenplaylistorderingstrategies.RatingOrderStrategy");
        Class<?> playerClass = Class.forName("de.tum.cit.aet.exgenplaylistorderingstrategies.Player");
        Constructor<?> ctor = playerClass.getConstructor(PlaybackStrategy.class);
        Object player = ctor.newInstance(ratingStrat);
        Method getPlaybackOrder = playerClass.getMethod("getPlaybackOrder", Playlist.class);
        @SuppressWarnings("unchecked")
        List<Track> order = (List<Track>) getPlaybackOrder.invoke(player, playlist);
        List<Track> expected = new ArrayList<>();
        expected.add(new Track("B", "Artist2", 5, 200));
        expected.add(new Track("C", "Artist3", 5, 210));
        expected.add(new Track("A", "Artist1", 3, 180));
        Assertions.assertEquals(expected, order, "Player should delegate to RatingOrderStrategy");
    }
