import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.Arrays;

/**
 * Minimal reflection utilities required by the exercise tests.
 * This implementation mirrors the behaviour of the library's {@code ReflectionTestUtils}
 * for the subset of methods used in the provided tests.
 */
public class ReflectionTestUtils {

    /**
     * Creates a new instance of the class with the given fully qualified name.
     * The method resolves a matching constructor based on the runtime types of {@code args}.
     */
    @SuppressWarnings("unchecked")
    public static <T> T newInstance(String className, Object... args) throws Exception {
        Class<?> clazz = Class.forName(className);
        if (args == null || args.length == 0) {
            Constructor<?> ctor = clazz.getConstructor();
            return (T) ctor.newInstance();
        }
        Class<?>[] paramTypes = Arrays.stream(args).map(Object::getClass).toArray(Class[]::new);
        Constructor<?> ctor = clazz.getConstructor(paramTypes);
        return (T) ctor.newInstance(args);
    }

    /** Returns the {@link Method} object for the given name and parameter types on the target's class. */
    public static Method getMethod(Object target, String name, Class<?>... paramTypes) throws Exception {
        return target.getClass().getMethod(name, paramTypes);
    }

    /** Invokes the given method on the target with supplied arguments. */
    public static Object invokeMethod(Object target, Method method, Object... args) throws Exception {
        return method.invoke(target, args);
    }

    /** Loads a class by its fully qualified name. */
    public static Class<?> getClazz(String className) throws ClassNotFoundException {
        return Class.forName(className);
    }
}
